import json

def transform_v3(grid):
    """
    For each row:
    1. Main vertical line at main_vert_col (full)
    2. Main horizontal line at main_horiz_row (left to right boundary)
    3. For other rows with 2s left of main vertical: fill up to main vertical or last 2
    4. For other rows with 2s right of main vertical: fill from main vertical or first 2
    """
    rows = len(grid)
    if rows == 0:
        return []
    cols = len(grid[0])

    blues = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == 1]

    main_vert_col = None
    main_horiz_row = None

    # Find main vertical line column
    for c in range(cols):
        has_top = any(grid[r][c] == 1 for r in range(rows))
        has_bottom = any(grid[r][c] == 1 for r in range(rows))
        if has_top and has_bottom:
            main_vert_col = c
            break

    # Find main horizontal line row  
    for r in range(rows):
        has_left = any(grid[r][c] == 1 for c in range(cols))
        has_right = any(grid[r][c] == 1 for c in range(cols))
        if has_left and has_right:
            main_horiz_row = r
            break

    if main_vert_col is None or main_horiz_row is None:
        main_vert_col = cols // 2
        main_horiz_row = rows // 2

    output = [[0] * cols for _ in range(rows)]

    # Main vertical (full)
    for r in range(rows):
        output[r][main_vert_col] = 1

    # Main horizontal (between leftmost and rightmost blue)
    leftmost_blue = min(b[1] for b in blues)
    rightmost_blue = max(b[1] for b in blues)
    for c in range(leftmost_blue, rightmost_blue + 1):
        output[main_horiz_row][c] = 1

    # Left segments
    for r in range(rows):
        if r == main_horiz_row:
            continue
        left_2s = [c for c in range(cols) if grid[r][c] == 2 and c < main_vert_col]
        if left_2s:
            start = min(left_2s)
            end = main_vert_col - 1
            if start < end + 1:
                for c in range(start, end + 1):
                    output[r][c] = 1

    # Right segments  
    for r in range(rows):
        if r == main_horiz_row:
            continue
        right_2s = [c for c in range(cols) if grid[r][c] == 2 and c > main_vert_col]
        if right_2s:
            start = main_vert_col + 1
            end = max(right_2s)
            if start <= end:
                for c in range(start, end + 1):
                    output[r][c] = 1

    return output

