                if any(grid[r][c] == 1 and c == c_max_hex for c in range(cols)):
                    main_horiz_row = r
                    break
    else:
        main_horiz_row = rows // 2

    output = [[0] * cols for _ in range(rows)]

    # Convert 2s to 1s
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                output[r][c] = 1
            elif grid[r][c] == 1:
